while True:
    page = apis.venmo.show_received_payment_requests(access_token=venmo_token, status='pending', page_index=page_index, page_limit=20)
    if not page:
        break
    pending_requests.extend(page)
    if len(page) < 20:
        break
    page_index += 1

print("Total pending requests:", len(pending_requests))
for req in pending_requests:
    print(req["payment_request_id"], req["sender"]["name"], req["sender"]["email"], req["amount"], req["description"])

